import{_ as a,a0 as n,w as u,s as l,ao as p,I as d,x as e,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"如何在 Ubuntu 上为用户授予和移除 sudo 权限 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上为用户授予和移除 sudo 权限 | LCTT (201902) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上为用户授予和移除 sudo 权限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上为用户授予和移除 sudo 权限 | LCTT (201902) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201902/20190216 How To Grant And Remove Sudo Privileges To Users On Ubuntu","title":"如何在 Ubuntu 上为用户授予和移除 sudo 权限","tag":"201902","desc":""},"relativePath":"201902/20190216 How To Grant And Remove Sudo Privileges To Users On Ubuntu.md","filePath":"[post].md"}'),r={name:"201902/20190216 How To Grant And Remove Sudo Privileges To Users On Ubuntu.md"};function h(c,s,g,b,k,f){const o=n("Link");return u(),l("div",null,[s[15]||(s[15]=p(`<h1 id="如何在-ubuntu-上为用户授予和移除-sudo-权限" tabindex="-1">如何在 Ubuntu 上为用户授予和移除 sudo 权限 <a class="header-anchor" href="#如何在-ubuntu-上为用户授予和移除-sudo-权限" aria-label="Permalink to “如何在 Ubuntu 上为用户授予和移除 sudo 权限”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/sudo-privileges-720x340.png" alt=""></p><p>如你所知，用户可以在 Ubuntu 系统上使用 sudo 权限执行任何管理任务。在 Linux 机器上创建新用户时，他们无法执行任何管理任务，直到你将其加入 <code>sudo</code> 组的成员。在这个简短的教程中，我们将介绍如何将普通用户添加到 <code>sudo</code> 组以及移除给定的权限，使其成为普通用户。</p><h3 id="在-linux-上向普通用户授予-sudo-权限" tabindex="-1">在 Linux 上向普通用户授予 sudo 权限 <a class="header-anchor" href="#在-linux-上向普通用户授予-sudo-权限" aria-label="Permalink to “在 Linux 上向普通用户授予 sudo 权限”">​</a></h3><p>通常，我们使用 <code>adduser</code> 命令创建新用户，如下所示。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo adduser ostechnix</span></span></code></pre></div><p>如果你希望新创建的用户使用 <code>sudo</code> 执行管理任务，只需使用以下命令将它添加到 <code>sudo</code> 组：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -a -G sudo hduser</span></span></code></pre></div><p>上面的命令将使名为 <code>ostechnix</code> 的用户成为 <code>sudo</code> 组的成员。</p><p>你也可以使用此命令将用户添加到 <code>sudo</code> 组。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo adduser ostechnix sudo</span></span></code></pre></div><p>现在，注销并以新用户身份登录，以使此更改生效。此时用户已成为管理用户。</p><p>要验证它，只需在任何命令中使用 <code>sudo</code> 作为前缀。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir /test</span></span>
<span class="line"><span>[sudo] password for ostechnix:</span></span></code></pre></div><h3 id="移除用户的-sudo-权限" tabindex="-1">移除用户的 sudo 权限 <a class="header-anchor" href="#移除用户的-sudo-权限" aria-label="Permalink to “移除用户的 sudo 权限”">​</a></h3><p>有时，你可能希望移除特定用户的 <code>sudo</code> 权限，而不用在 Linux 中删除它。要将任何用户设为普通用户，只需将其从 <code>sudo</code> 组中删除即可。</p><p>比如说如果要从 <code>sudo</code> 组中删除名为 <code>ostechnix</code> 的用户，只需运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo deluser ostechnix sudo</span></span></code></pre></div><p>示例输出：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Removing user \`ostechnix&#39; from group \`sudo&#39; ...</span></span>
<span class="line"><span>Done.</span></span></code></pre></div><p>此命令仅从 <code>sudo</code> 组中删除用户 <code>ostechnix</code>，但不会永久地从系统中删除用户。现在，它成为了普通用户，无法像 <code>sudo</code> 用户那样执行任何管理任务。</p><p>此外，你可以使用以下命令撤消用户的 <code>sudo</code> 访问权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo gpasswd -d ostechnix sudo</span></span></code></pre></div><p>从 <code>sudo</code> 组中删除用户时请小心。不要从 <code>sudo</code> 组中删除真正的管理员。</p><p>使用命令验证用户 <code>ostechnix</code> 是否已从 <code>sudo</code> 组中删除：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo -l -U ostechnix</span></span>
<span class="line"><span>User ostechnix is not allowed to run sudo on ubuntuserver.</span></span></code></pre></div><p>是的，用户 <code>ostechnix</code> 已从 <code>sudo</code> 组中删除，他无法执行任何管理任务。</p><p>从 <code>sudo</code> 组中删除用户时请小心。如果你的系统上只有一个 <code>sudo</code> 用户，并且你将他从 <code>sudo</code> 组中删除了，那么就无法执行任何管理操作，例如在系统上安装、删除和更新程序。所以，请小心。在我们的下一篇教程中，我们将解释如何恢复用户的 <code>sudo</code> 权限。</p><p>就是这些了。希望这篇文章有用。还有更多好东西。敬请期待！</p><p>干杯!</p><hr>`,31)),d("p",null,[s[1]||(s[1]=e("via: ",-1)),i(o,{href:"https://www.ostechnix.com/how-to-grant-and-remove-sudo-privileges-to-users-on-ubuntu/"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.ostechnix.com/how-to-grant-and-remove-sudo-privileges-to-users-on-ubuntu/",-1)])]),_:1})]),d("p",null,[s[6]||(s[6]=e("作者：",-1)),i(o,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[e("SK",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),i(o,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),i(o,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),i(o,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),d("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(o,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),i(o,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=a(r,[["render",h]]);export{v as __pageData,C as default};
